 $p=$id?one('SELECT * FROM '.table('projects').' WHERE id=?',[$id]):[];if($id&&!$p){echo '<div class="notice error">Project not found.</div>';admin_foot();exit;}$p=$p?:['title'=>'','slug'=>'','category'=>'','summary'=>'','description'=>'','challenge'=>'','solution'=>'','deliverables'=>'','website_url'=>'','status'=>'draft','sort_order'=>0,'featured'=>0,'is_demo'=>0,'media_id'=>null,'cover'=>''];if($error&&$_SERVER['REQUEST_METHOD']==='POST'){foreach($p as $k=>$v)if(isset($_POST[$k])&&is_string($_POST[$k]))$p[$k]=$_POST[$k];}
 ?><form method="post" enctype="multipart/form-data" class="editor-layout" action="<?=esc(admin_url('project',['id'=>$id]))?>"><?php admin_action('project_save');?><input type="hidden" name="id" value="<?=$id?>"><div class="admin-card"><div class="card-header"><h2>The project story</h2></div><?php admin_input('title','Project title',$p['title'],'text','required maxlength="160"');?><div class="field-grid"><?php admin_input('slug','URL slug',$p['slug'],'text','maxlength="160" placeholder="generated-from-title"');admin_input('category','Category',$p['category'],'text','required maxlength="80" placeholder="Hospitality, Retail, Construction…"');?></div><?php admin_textarea('summary','Short portfolio introduction',$p['summary'],3,2000);admin_textarea('description','Project overview',$p['description'],6,16000);admin_textarea('challenge','The challenge',$p['challenge'],4);admin_textarea('solution','Your approach / solution',$p['solution'],4);admin_textarea('deliverables','Deliverables',$p['deliverables'],3);admin_input('website_url','Live website URL (optional)',$p['website_url'],'url','maxlength="500" placeholder="https://…"');?><p class="hint">Text is safely displayed as plain text. Use paragraphs; HTML and scripts are not rendered.</p></div><aside><section class="admin-card"><div class="card-header"><h2>Publication</h2></div><?php admin_select('status','Visibility',['draft'=>'Draft — hidden from the public','published'=>'Published — visible on website'],$p['status']);admin_input('sort_order','Display order',$p['sort_order'],'number','min="-9999" max="9999"');admin_check('featured','Feature on the homepage',$p['featured']);admin_check('is_demo','Clearly label this as a design concept',$p['is_demo']);?><p class="hint">The homepage shows the first three featured, published projects in display order.</p><button class="btn gold wide">Save Project →</button></section><section class="admin-card"><div class="card-header"><h2>Project image</h2></div><?php if($p['media_id']||$p['cover']):?><img class="editor-preview" src="<?=esc(image_url($p))?>" alt="Current project image"><?php endif;?><label>Upload a replacement<input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><p class="hint">JPG, PNG or WebP · up to 6 MB / 16 megapixels. Images are decoded and re-encoded by the server. SVG and executable uploads are rejected.</p><?php admin_check('remove_image','Remove the current image',false);?></section><?php if($id&&$p['status']==='published'):?><a class="text-link" href="<?=esc(page_url('project',['slug'=>$p['slug']]))?>" target="_blank" rel="noopener">Preview public project ↗</a><?php endif;?></aside></form><?php if($id):?><form class="delete-form" method="post" action="<?=esc(admin_url('project',['id'=>$id]))?>" data-confirm="Permanently delete this portfolio project? Its unused image can be removed later in System health."><?php admin_action('project_delete');?><input type="hidden" name="id" value="<?=$id?>"><button class="btn danger small">Delete Project</button></form><?php endif;
